<!--
 * 消息批量发送表单组件
 *
 * @path apps/message-web/src/views/batch/batch-form.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为契约 API：批量提交表单（BatchSendRequestDTO）提交 submitBatch()。
-->
<script lang="ts" setup>
/**
 * 消息批量发送（表单组件）
 * <p>消费后端契约 BatchController#submitBatch（src/api/batch.ts，auto-generated by bash/gen-contract.py）：
 * 按 BatchSendRequestDTO 字段（batchName/channel/templateCode/bizType/receiverList/async/senderId）填写
 * 并提交批量发送，成功后 emit('success', MsgBatchVO) 并关闭弹窗。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { useYdModal } from '@ydsz/common-ui';
import { YdForm, YdFormItem, YdButton, YdInput, YdRadioGroup, YdRadioGroupItem, YdTextarea } from '@ydsz-core/ydsz-ui';
import { reactive, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { submitBatch } from '#/api/batch';
import type { BatchSendRequestDTO, MsgBatchVO } from '#/api/models';

const emit = defineEmits<{ success: [batch: MsgBatchVO] }>();

const { t } = useI18n();

const formRef = ref();

/** 批量提交表单状态（字段对应 BatchSendRequestDTO，receiverList 以文本域录入后拆分） */
interface BatchFormState {
  batchName: string;
  channel: string;
  templateCode: string;
  bizType: string;
  receiverListText: string;
  async: boolean;
  senderId: string;
}

const formData = reactive<BatchFormState>({
  batchName: '',
  channel: '',
  templateCode: '',
  bizType: '',
  receiverListText: '',
  async: false,
  senderId: '',
});

const rules = {
  batchName: [{ required: true, message: '请输入批次名称', trigger: 'blur' }],
  receiverListText: [{ required: true, message: '请输入接收者列表', trigger: 'blur' }],
};

/** 文本域按换行/逗号拆分接收者列表 */
function parseReceiverList(): string[] {
  return formData.receiverListText
    .split(/[\n,;，；]/)
    .map((item) => item.trim())
    .filter((item) => item !== '');
}

const [Modal, modalApi] = useYdModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    Object.assign(formData, {
      batchName: '',
      channel: '',
      templateCode: '',
      bizType: '',
      receiverListText: '',
      async: false,
      senderId: '',
    });
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch {
      return;
    }
    modalApi.lock();
    try {
      const data: BatchSendRequestDTO = {
        batchName: formData.batchName,
        channel: formData.channel || undefined,
        templateCode: formData.templateCode || undefined,
        bizType: formData.bizType || undefined,
        receiverList: parseReceiverList(),
        async: formData.async,
        senderId: formData.senderId || undefined,
      };
      const batch = await submitBatch(data);
      showToast.success('批量任务提交成功');
      emit('success', batch);
      modalApi.close();
    } finally {
      modalApi.unlock();
    }
  },
});
</script>
<template>
  <Modal title="提交批量发送">
    <YdForm
      ref="formRef"
      :model="formData"
      :rules="rules"
      label-width="100px"
      label-position="right"
    >
      <YdFormItem label="批次名称" prop="batchName">
        <YdInput v-model="formData.batchName" placeholder="请输入批次名称" />
      </YdFormItem>
      <YdFormItem label="通道" prop="channel">
        <YdInput v-model="formData.channel" placeholder="请输入通道，如 SMS/EMAIL/IN_APP" />
      </YdFormItem>
      <YdFormItem :label="t('templateCode')" prop="templateCode">
        <YdInput v-model="formData.templateCode" :placeholder="t('templateCode')" />
      </YdFormItem>
      <YdFormItem label="业务类型" prop="bizType">
        <YdInput v-model="formData.bizType" placeholder="请输入业务类型（可为空）" />
      </YdFormItem>
      <YdFormItem label="接收者列表" prop="receiverListText">
        <YdTextarea
          v-model="formData.receiverListText"
          placeholder="每行一个接收者，支持逗号/分号/换行分隔"
        />
      </YdFormItem>
      <YdFormItem label="是否异步" prop="async">
        <YdRadioGroup v-model="formData.async">
          <YdRadioGroupItem :value="true">异步</YdRadioGroupItem>
          <YdRadioGroupItem :value="false">同步</YdRadioGroupItem>
        </YdRadioGroup>
      </YdFormItem>
      <YdFormItem label="发送人" prop="senderId">
        <YdInput v-model="formData.senderId" placeholder="请输入发送人（可为空）" />
      </YdFormItem>
    </YdForm>
  </Modal>
</template>
